package index

import (
	"context"
	"database/sql"
	"fmt"
	"strings"
)

// detectAnchorKind determines the kind of anchor based on its string format.
func detectAnchorKind(a string) string {
	trimmed := strings.TrimSpace(a)
	if strings.HasPrefix(trimmed, "symbol:") || strings.Contains(trimmed, "#") {
		return "symbol"
	}
	if strings.HasPrefix(trimmed, "file:") {
		return "file"
	}
	if strings.HasPrefix(trimmed, "cmd:") || strings.HasPrefix(trimmed, "command:") {
		return "command"
	}
	return "file"
}

// UpsertEntryAnchors replaces all anchors for a given entry.
func (idx *Index) UpsertEntryAnchors(ctx context.Context, entryID string, anchors []string) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors WHERE entry_id = ?", entryID); err != nil {
			return fmt.Errorf("deleting existing anchors for %s: %w", entryID, err)
		}
		if len(anchors) == 0 {
			return nil
		}
		stmt, err := tx.PrepareContext(ctx, "INSERT INTO entry_anchors (entry_id, anchor, kind, fingerprint) VALUES (?, ?, ?, ?)")
		if err != nil {
			return err
		}
		defer stmt.Close()

		for _, a := range anchors {
			trimmed := strings.TrimSpace(a)
			if trimmed == "" {
				continue
			}
			kind := detectAnchorKind(trimmed)
			if _, err := stmt.ExecContext(ctx, entryID, trimmed, kind, ""); err != nil {
				return fmt.Errorf("inserting anchor %s for %s: %w", trimmed, entryID, err)
			}
		}
		return nil
	})
}

// LookupByAnchor returns entry IDs matching the anchor using prefix matching (LIKE 'pattern%').
func (idx *Index) LookupByAnchor(ctx context.Context, anchor string) ([]string, error) {
	trimmed := strings.TrimSpace(anchor)
	pattern := trimmed
	if !strings.HasSuffix(pattern, "%") {
		pattern += "%"
	}

	rows, err := idx.db.QueryContext(ctx, `
		SELECT DISTINCT entry_id
		FROM entry_anchors
		WHERE anchor LIKE ?
		ORDER BY entry_id ASC
	`, pattern)
	if err != nil {
		return nil, fmt.Errorf("lookup by anchor %s: %w", anchor, err)
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		results = append(results, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if results == nil {
		results = []string{}
	}
	return results, nil
}

// LookupByAnchorExact returns entry IDs matching the anchor exactly.
func (idx *Index) LookupByAnchorExact(ctx context.Context, anchor string) ([]string, error) {
	trimmed := strings.TrimSpace(anchor)
	rows, err := idx.db.QueryContext(ctx, `
		SELECT DISTINCT entry_id
		FROM entry_anchors
		WHERE anchor = ?
		ORDER BY entry_id ASC
	`, trimmed)
	if err != nil {
		return nil, fmt.Errorf("lookup by anchor exact %s: %w", anchor, err)
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		results = append(results, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if results == nil {
		results = []string{}
	}
	return results, nil
}

