var ErrEntryNotFound = sql.ErrNoRows

// ErrorPatternResult represents a failure signature pattern match candidate.
type ErrorPatternResult struct {
	EntryID       string `json:"entry_id"`
	CommandPrefix string `json:"command_prefix"`
	Pattern       string `json:"pattern"`
	DossierScope  string `json:"dossier_scope"`
}

// UpsertEntry inserts or updates an entry and syncs its anchors if present.
func (idx *Index) UpsertEntry(ctx context.Context, entry dossiers.Entry) error {
	var createdAtStr, updatedAtStr string
	if !entry.CreatedAt.IsZero() {
		createdAtStr = entry.CreatedAt.UTC().Format(time.RFC3339Nano)
	} else {
		createdAtStr = time.Now().UTC().Format(time.RFC3339Nano)
	}
	if !entry.UpdatedAt.IsZero() {
		updatedAtStr = entry.UpdatedAt.UTC().Format(time.RFC3339Nano)
	} else {
		updatedAtStr = createdAtStr
	}

	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		query := `
		INSERT INTO entries (id, type, dossier_scope, text, source, verified, closes_when, created_at, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(id) DO UPDATE SET
			type = excluded.type,
			dossier_scope = excluded.dossier_scope,
			text = excluded.text,
			source = excluded.source,
			verified = excluded.verified,
			closes_when = excluded.closes_when,
			created_at = excluded.created_at,
			updated_at = excluded.updated_at
		`
		_, err := tx.ExecContext(ctx, query,
			entry.ID,
			string(entry.Type),
			entry.DossierScope,
			entry.Text,
			entry.Source,
			entry.Verified,
			entry.ClosesWhen,
			createdAtStr,
			updatedAtStr,
		)
		if err != nil {
			return fmt.Errorf("upserting entry %s: %w", entry.ID, err)
		}

		if len(entry.Anchors) > 0 {
			if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors WHERE entry_id = ?", entry.ID); err != nil {
				return err
			}
			stmt, err := tx.PrepareContext(ctx, "INSERT INTO entry_anchors (entry_id, anchor, kind, fingerprint) VALUES (?, ?, ?, ?)")
			if err != nil {
				return err
			}
			defer stmt.Close()
			for _, a := range entry.Anchors {
				trimmed := strings.TrimSpace(a)
				if trimmed == "" {
					continue
				}
				kind := detectAnchorKind(trimmed)
				if _, err := stmt.ExecContext(ctx, entry.ID, trimmed, kind, ""); err != nil {
					return err
				}
			}
		}

		return nil
	})
}

// GetEntry retrieves an entry by its ID, including its associated anchors.
func (idx *Index) GetEntry(ctx context.Context, id string) (*dossiers.Entry, error) {
	row := idx.db.QueryRowContext(ctx, `
		SELECT id, type, dossier_scope, text, source, verified, closes_when, created_at, updated_at
		FROM entries
		WHERE id = ?
	`, id)

	var e dossiers.Entry
	var entryType string
	var source, verified, closesWhen, createdAtStr, updatedAtStr sql.NullString

	err := row.Scan(&e.ID, &entryType, &e.DossierScope, &e.Text, &source, &verified, &closesWhen, &createdAtStr, &updatedAtStr)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrEntryNotFound
		}
		return nil, fmt.Errorf("getting entry %s: %w", id, err)
	}

	e.Type = dossiers.EntryType(entryType)
	e.Source = source.String
	e.Verified = verified.String
	e.ClosesWhen = closesWhen.String
	if createdAtStr.Valid && createdAtStr.String != "" {
		if t, err := time.Parse(time.RFC3339Nano, createdAtStr.String); err == nil {
			e.CreatedAt = t
		} else if t, err := time.Parse(time.RFC3339, createdAtStr.String); err == nil {
			e.CreatedAt = t
		}
	}
	if updatedAtStr.Valid && updatedAtStr.String != "" {
		if t, err := time.Parse(time.RFC3339Nano, updatedAtStr.String); err == nil {
			e.UpdatedAt = t
		} else if t, err := time.Parse(time.RFC3339, updatedAtStr.String); err == nil {
			e.UpdatedAt = t
		}
	}

	anchors, err := idx.loadAnchorsForEntry(ctx, id)
	if err != nil {
		return nil, fmt.Errorf("loading anchors for entry %s: %w", id, err)
	}
	e.Anchors = anchors

	return &e, nil
}

// DeleteEntry deletes an entry and its associated anchors, error patterns, and FTS index record.
func (idx *Index) DeleteEntry(ctx context.Context, id string) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM entry_anchors WHERE entry_id = ?", id); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM error_patterns WHERE entry_id = ?", id); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, "DELETE FROM entries WHERE id = ?", id); err != nil {
			return err
		}
		return nil
	})
}

// ListEntriesByScope returns all entries belonging to the specified dossier scope.
func (idx *Index) ListEntriesByScope(ctx context.Context, scope string) ([]dossiers.Entry, error) {
	rows, err := idx.db.QueryContext(ctx, `
		SELECT id, type, dossier_scope, text, source, verified, closes_when, created_at, updated_at
		FROM entries
		WHERE dossier_scope = ?
		ORDER BY id ASC
	`, scope)
	if err != nil {
		return nil, fmt.Errorf("listing entries for scope %s: %w", scope, err)
	}
	defer rows.Close()

	var entries []dossiers.Entry
	for rows.Next() {
		var e dossiers.Entry
		var entryType string
		var source, verified, closesWhen, createdAtStr, updatedAtStr sql.NullString
		if err := rows.Scan(&e.ID, &entryType, &e.DossierScope, &e.Text, &source, &verified, &closesWhen, &createdAtStr, &updatedAtStr); err != nil {
			return nil, err
		}
		e.Type = dossiers.EntryType(entryType)
		e.Source = source.String
		e.Verified = verified.String
		e.ClosesWhen = closesWhen.String
		if createdAtStr.Valid && createdAtStr.String != "" {
			if t, err := time.Parse(time.RFC3339Nano, createdAtStr.String); err == nil {
				e.CreatedAt = t
			} else if t, err := time.Parse(time.RFC3339, createdAtStr.String); err == nil {
				e.CreatedAt = t
			}
		}
		if updatedAtStr.Valid && updatedAtStr.String != "" {
			if t, err := time.Parse(time.RFC3339Nano, updatedAtStr.String); err == nil {
				e.UpdatedAt = t
			} else if t, err := time.Parse(time.RFC3339, updatedAtStr.String); err == nil {
				e.UpdatedAt = t
			}
		}
		entries = append(entries, e)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	for i := range entries {
		anchors, err := idx.loadAnchorsForEntry(ctx, entries[i].ID)
		if err != nil {
			return nil, err
		}
		entries[i].Anchors = anchors
	}

	if entries == nil {
		entries = []dossiers.Entry{}
	}
	return entries, nil
}

// SearchEntries searches entries using full-text search over entries_fts.
func (idx *Index) SearchEntries(ctx context.Context, query string) ([]dossiers.Entry, error) {
