		SELECT e.id, e.type, e.dossier_scope, e.text, e.source, e.verified, e.closes_when, e.created_at, e.updated_at
		FROM entries_fts f
		JOIN entries e ON f.rowid = e.rowid
		WHERE entries_fts MATCH ?
		ORDER BY bm25(entries_fts)
	`, trimmed)
