// loadAnchorsForEntry loads all anchors for an entry.
func (idx *Index) loadAnchorsForEntry(ctx context.Context, entryID string) ([]string, error) {
	rows, err := idx.db.QueryContext(ctx, `
		SELECT anchor
		FROM entry_anchors
		WHERE entry_id = ?
		ORDER BY rowid ASC
	`, entryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var anchors []string
	for rows.Next() {
		var a string
		if err := rows.Scan(&a); err != nil {
			return nil, err
		}
		anchors = append(anchors, a)
	}
	return anchors, rows.Err()
}

// InsertErrorPattern registers an error pattern for a failure signature entry.
func (idx *Index) InsertErrorPattern(ctx context.Context, entryID, commandPrefix, pattern, scope string) error {
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		query := `
		INSERT INTO error_patterns (entry_id, command_prefix, pattern, dossier_scope)
		VALUES (?, ?, ?, ?)
		`
		_, err := tx.ExecContext(ctx, query, entryID, commandPrefix, pattern, scope)
		if err != nil {
			return fmt.Errorf("inserting error pattern for entry %s: %w", entryID, err)
		}
		return nil
	})
}

// LookupErrorPatterns returns matching failure-signature entries for a command prefix.
func (idx *Index) LookupErrorPatterns(ctx context.Context, commandPrefix string) ([]ErrorPatternResult, error) {
	trimmed := strings.TrimSpace(commandPrefix)
	var rows *sql.Rows
	var err error

	if trimmed == "" {
		rows, err = idx.db.QueryContext(ctx, `
			SELECT entry_id, COALESCE(command_prefix, ''), pattern, dossier_scope
			FROM error_patterns
			ORDER BY entry_id ASC
		`)
	} else {
		query := `
		SELECT entry_id, COALESCE(command_prefix, ''), pattern, dossier_scope
		FROM error_patterns
		WHERE command_prefix = ?
		   OR ? LIKE (command_prefix || '%')
		   OR command_prefix LIKE (? || '%')
		   OR command_prefix IS NULL
		   OR command_prefix = ''
		ORDER BY entry_id ASC
		`
		rows, err = idx.db.QueryContext(ctx, query, trimmed, trimmed, trimmed)
	}

	if err != nil {
		return nil, fmt.Errorf("lookup error patterns for command %s: %w", commandPrefix, err)
	}
	defer rows.Close()

	var results []ErrorPatternResult
	for rows.Next() {
		var res ErrorPatternResult
		if err := rows.Scan(&res.EntryID, &res.CommandPrefix, &res.Pattern, &res.DossierScope); err != nil {
			return nil, err
		}
		results = append(results, res)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if results == nil {
		results = []ErrorPatternResult{}
	}
	return results, nil
}

// UpsertAlias updates or registers a scope alias mapping oldScope to newScope.
func (idx *Index) UpsertAlias(ctx context.Context, oldScope, newScope string) error {
	oldScope = strings.TrimSpace(oldScope)
	newScope = strings.TrimSpace(newScope)
	if oldScope == "" || newScope == "" {
		return fmt.Errorf("oldScope and newScope cannot be empty")
	}

	now := time.Now().UTC().Format(time.RFC3339)
	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, "DELETE FROM aliases WHERE old_scope = ?", oldScope); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, "INSERT INTO aliases (old_scope, new_scope, created_at) VALUES (?, ?, ?)", oldScope, newScope, now)
		return err
	})
}

// ResolveAlias follows the alias chain in the index to return the target scope name.
func (idx *Index) ResolveAlias(ctx context.Context, scope string) (string, error) {
	current := strings.TrimSpace(scope)
	if current == "" {
		return "", nil
	}

	maxDepth := 10
	visited := make(map[string]bool)

	for depth := 0; depth < maxDepth; depth++ {
		var next string
		err := idx.db.QueryRowContext(ctx, "SELECT new_scope FROM aliases WHERE old_scope = ? LIMIT 1", current).Scan(&next)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return current, nil
			}
			return "", fmt.Errorf("resolving alias for %s: %w", current, err)
		}
		next = strings.TrimSpace(next)
		if next == "" || next == current || visited[next] {
			break
		}
		visited[current] = true
		current = next
	}

	return current, nil
}

// InsertHistory records an entry in the history table.
func (idx *Index) InsertHistory(ctx context.Context, entry dossiers.Entry, reason string) error {
	if reason == "" && entry.RetiredReason != "" {
		reason = entry.RetiredReason
	}
	historyID := fmt.Sprintf("hist-%s-%d", entry.ID, time.Now().UnixNano())
	var retiredAt string
	if !entry.UpdatedAt.IsZero() {
		retiredAt = entry.UpdatedAt.UTC().Format(time.RFC3339Nano)
	} else {
		retiredAt = time.Now().UTC().Format(time.RFC3339Nano)
	}

	return idx.WriteTx(ctx, func(tx *sql.Tx) error {
		query := `
		INSERT INTO entry_history (id, entry_id, type, dossier_scope, text, reason, superseded_by, retired_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?)
		`
		_, err := tx.ExecContext(ctx, query,
			historyID,
			entry.ID,
			string(entry.Type),
			entry.DossierScope,
			entry.Text,
			reason,
			entry.SupersededBy,
			retiredAt,
		)
		if err != nil {
			return fmt.Errorf("inserting entry history for %s: %w", entry.ID, err)
		}
		return nil
	})
}

// GetHistory retrieves history entries for an entry ID.
func (idx *Index) GetHistory(ctx context.Context, entryID string) ([]dossiers.Entry, error) {
	rows, err := idx.db.QueryContext(ctx, `
		SELECT entry_id, type, dossier_scope, text, reason, superseded_by, retired_at
		FROM entry_history
		WHERE entry_id = ?
		ORDER BY rowid ASC
	`, entryID)
	if err != nil {
		return nil, fmt.Errorf("getting history for entry %s: %w", entryID, err)
	}
	defer rows.Close()

	var history []dossiers.Entry
	for rows.Next() {
		var e dossiers.Entry
		var entryType string
		var text, reason, supersededBy, retiredAt sql.NullString
		if err := rows.Scan(&e.ID, &entryType, &e.DossierScope, &text, &reason, &supersededBy, &retiredAt); err != nil {
			return nil, err
		}
		e.Type = dossiers.EntryType(entryType)
		e.Text = text.String
		e.Retired = true
		e.RetiredReason = reason.String
		e.SupersededBy = supersededBy.String
		if retiredAt.Valid && retiredAt.String != "" {
			if t, err := time.Parse(time.RFC3339Nano, retiredAt.String); err == nil {
				e.UpdatedAt = t
			} else if t, err := time.Parse(time.RFC3339, retiredAt.String); err == nil {
				e.UpdatedAt = t
			}
		}
		history = append(history, e)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if history == nil {
		history = []dossiers.Entry{}
	}
	return history, nil
}

