var RebuildIndex = Rebuild

// RebuildFromOpLog rebuilds all v2 index tables from the op log.
func (idx *Index) RebuildFromOpLog(ctx context.Context, opsReader *ops.Reader) error {
	if opsReader == nil {
		return fmt.Errorf("opsReader cannot be nil")
	}

	// 1. Clear all v2 tables
	err := idx.WriteTx(ctx, func(tx *sql.Tx) error {
		tables := []string{
			"entry_anchors",
			"error_patterns",
			"aliases",
			"entry_history",
			"entries",
		}
		for _, t := range tables {
			if _, err := tx.ExecContext(ctx, fmt.Sprintf("DELETE FROM %s", t)); err != nil {
				return fmt.Errorf("clearing table %s: %w", t, err)
			}
		}
		return nil
	})
	if err != nil {
		return err
	}

	// Clear FTS index
	_, _ = idx.db.ExecContext(ctx, "INSERT INTO entries_fts(entries_fts) VALUES('delete-all')")

	// Collect any error pattern metadata from ops in opsReader
	type errPatMeta struct {
		commandPrefix string
		pattern       string
	}
	opMeta := make(map[string]errPatMeta)
	for batch, err := range opsReader.Iterate(ctx) {
		if err != nil {
			return fmt.Errorf("reading ops: %w", err)
		}
		if batch == nil {
			continue
		}
		for _, op := range batch.Ops {
			if op.EntryID != "" {
				var cmdPrefix, pattern string
				if cp, ok := op.Fields["command_prefix"].(string); ok {
					cmdPrefix = cp
				}
				if pat, ok := op.Fields["pattern"].(string); ok {
					pattern = pat
				}
				if cmdPrefix != "" || pattern != "" {
					opMeta[op.EntryID] = errPatMeta{
						commandPrefix: cmdPrefix,
						pattern:       pattern,
					}
				}
			}
		}
	}

	// 2. Project dossiers from op log
	projector := dossiers.NewProjector(opsReader)
	dossierMap, err := projector.Project(ctx)
	if err != nil {
		return fmt.Errorf("projecting dossiers: %w", err)
	}

	// Sort scopes for deterministic ordering
	var scopes []string
	for scope := range dossierMap {
		scopes = append(scopes, scope)
	}
	sort.Strings(scopes)

	// 3. For each dossier and its entries: UpsertEntry, UpsertEntryAnchors
	//    For failure-signature entries: InsertErrorPattern
	//    For retired/superseded entries in History: InsertHistory
	for _, scope := range scopes {
		dossier := dossierMap[scope]
		if dossier == nil {
			continue
		}

		for _, entry := range dossier.Entries {
			if err := idx.UpsertEntry(ctx, entry); err != nil {
				return fmt.Errorf("upserting entry %s: %w", entry.ID, err)
			}
			if err := idx.UpsertEntryAnchors(ctx, entry.ID, entry.Anchors); err != nil {
				return fmt.Errorf("upserting anchors for entry %s: %w", entry.ID, err)
			}

			if entry.Type == dossiers.EntryTypeFailureSignature {
				meta := opMeta[entry.ID]
				cmdPrefix := meta.commandPrefix
				pat := meta.pattern
				if pat == "" {
					pat = entry.Text
				}
				if cmdPrefix == "" {
					for _, a := range entry.Anchors {
						if strings.HasPrefix(a, "cmd:") {
							cmdPrefix = strings.TrimPrefix(a, "cmd:")
							break
						} else if strings.HasPrefix(a, "command:") {
							cmdPrefix = strings.TrimPrefix(a, "command:")
							break
						}
					}
				}
				if err := idx.InsertErrorPattern(ctx, entry.ID, cmdPrefix, pat, entry.DossierScope); err != nil {
					return fmt.Errorf("inserting error pattern for entry %s: %w", entry.ID, err)
				}
			}
		}

		for _, histEntry := range dossier.History {
			reason := histEntry.RetiredReason
			if reason == "" {
				reason = "retired"
			}
			if err := idx.InsertHistory(ctx, histEntry, reason); err != nil {
				return fmt.Errorf("inserting history for entry %s: %w", histEntry.ID, err)
			}
		}
	}

	// 4. Build aliases from config.BuildAliasMap
	aliasMap, err := config.BuildAliasMap(opsReader, ctx)
	if err != nil {
		return fmt.Errorf("building alias map: %w", err)
	}
	for _, s := range aliasMap.AllAliases() {
		if aliasMap.HasAlias(s) {
			targets := aliasMap.Targets(s)
			if len(targets) > 0 {
				if err := idx.UpsertAlias(ctx, s, targets[0]); err != nil {
					return fmt.Errorf("upserting alias %s -> %s: %w", s, targets[0], err)
				}
			}
		}
	}

	// Rebuild FTS5 external content table to ensure 100% sync
	_, _ = idx.db.ExecContext(ctx, "INSERT INTO entries_fts(entries_fts) VALUES('rebuild')")

	return nil
}

