package index_test

import (
	"context"
	"path/filepath"
	"testing"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

func TestEntryRoundTrip(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	now := time.Now().UTC().Truncate(time.Second)
	entry := dossiers.Entry{
		ID:           "inv-storage-1",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/storage",
		Text:         "Storage must use append-only ops log",
		Anchors:      []string{"file:internal/core/storage.go", "symbol:AppendOp"},
		Source:       ops.SourceTurnNote,
		Verified:     "2026-10-10",
		ClosesWhen:   "never",
		CreatedAt:    now,
		UpdatedAt:    now,
	}

	// 1. Insert & Retrieve
	if err := idx.UpsertEntry(ctx, entry); err != nil {
		t.Fatalf("UpsertEntry: %v", err)
	}

	got, err := idx.GetEntry(ctx, entry.ID)
	if err != nil {
		t.Fatalf("GetEntry: %v", err)
	}
	if got.ID != entry.ID {
		t.Errorf("expected ID %s, got %s", entry.ID, got.ID)
	}
	if got.Type != entry.Type {
		t.Errorf("expected Type %s, got %s", entry.Type, got.Type)
	}
	if got.DossierScope != entry.DossierScope {
		t.Errorf("expected DossierScope %s, got %s", entry.DossierScope, got.DossierScope)
	}
	if got.Text != entry.Text {
		t.Errorf("expected Text %s, got %s", entry.Text, got.Text)
	}
	if got.Source != entry.Source {
		t.Errorf("expected Source %s, got %s", entry.Source, got.Source)
	}
	if got.Verified != entry.Verified {
		t.Errorf("expected Verified %s, got %s", entry.Verified, got.Verified)
	}
	if got.ClosesWhen != entry.ClosesWhen {
		t.Errorf("expected ClosesWhen %s, got %s", entry.ClosesWhen, got.ClosesWhen)
	}
	if len(got.Anchors) != 2 {
		t.Fatalf("expected 2 anchors, got %d", len(got.Anchors))
	}
	if got.Anchors[0] != entry.Anchors[0] || got.Anchors[1] != entry.Anchors[1] {
		t.Errorf("anchors mismatch: got %v, expected %v", got.Anchors, entry.Anchors)
	}

	// 2. Update
	entry.Text = "Updated invariant text"
	if err := idx.UpsertEntry(ctx, entry); err != nil {
		t.Fatalf("UpsertEntry (update): %v", err)
	}
	updated, err := idx.GetEntry(ctx, entry.ID)
	if err != nil {
		t.Fatalf("GetEntry after update: %v", err)
	}
	if updated.Text != "Updated invariant text" {
		t.Errorf("expected updated text, got %s", updated.Text)
	}

	// 3. ListEntriesByScope
	entry2 := dossiers.Entry{
		ID:           "rul-storage-2",
		Type:         dossiers.EntryTypeRuledOut,
		DossierScope: "core/storage",
		Text:         "Ruled out mutable logs",
	}
	entryOtherScope := dossiers.Entry{
		ID:           "inv-network-1",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/network",
		Text:         "Network must be TLS",
	}
	if err := idx.UpsertEntry(ctx, entry2); err != nil {
		t.Fatalf("UpsertEntry entry2: %v", err)
	}
	if err := idx.UpsertEntry(ctx, entryOtherScope); err != nil {
		t.Fatalf("UpsertEntry entryOtherScope: %v", err)
	}

	scopeList, err := idx.ListEntriesByScope(ctx, "core/storage")
	if err != nil {
		t.Fatalf("ListEntriesByScope: %v", err)
	}
	if len(scopeList) != 2 {
		t.Errorf("expected 2 entries in core/storage, got %d", len(scopeList))
	}

	// 4. DeleteEntry
	if err := idx.DeleteEntry(ctx, entry.ID); err != nil {
		t.Fatalf("DeleteEntry: %v", err)
	}
	_, err = idx.GetEntry(ctx, entry.ID)
	if err == nil {
		t.Errorf("expected error for deleted entry, got nil")
	}
}

func TestSearchEntries(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	entries := []dossiers.Entry{
		{
			ID:           "entry-1",
			Type:         dossiers.EntryTypeInvariant,
			DossierScope: "core/storage",
			Text:         "SQLite index rebuilds from append-only ops log",
		},
		{
			ID:           "entry-2",
			Type:         dossiers.EntryTypeDecision,
			DossierScope: "core/search",
			Text:         "FTS5 full text search indexing for memory plugin",
		},
		{
			ID:           "entry-3",
			Type:         dossiers.EntryTypeProcedure,
			DossierScope: "core/swap",
			Text:         "Pointer file atomic swap with symlink",
		},
	}

	for _, e := range entries {
		if err := idx.UpsertEntry(ctx, e); err != nil {
			t.Fatalf("UpsertEntry %s: %v", e.ID, err)
		}
	}

	// Search matching query
	results, err := idx.SearchEntries(ctx, "SQLite")
	if err != nil {
		t.Fatalf("SearchEntries SQLite: %v", err)
	}
	if len(results) != 1 || results[0].ID != "entry-1" {
		t.Errorf("expected entry-1, got results: %+v", results)
	}

	results, err = idx.SearchEntries(ctx, "search")
	if err != nil {
		t.Fatalf("SearchEntries search: %v", err)
	}
	if len(results) != 1 || results[0].ID != "entry-2" {
		t.Errorf("expected entry-2, got results: %+v", results)
	}

	results, err = idx.SearchEntries(ctx, "atomic")
	if err != nil {
		t.Fatalf("SearchEntries atomic: %v", err)
	}
	if len(results) != 1 || results[0].ID != "entry-3" {
		t.Errorf("expected entry-3, got results: %+v", results)
	}

	// Search non-matching query
	results, err = idx.SearchEntries(ctx, "banana")
	if err != nil {
		t.Fatalf("SearchEntries banana: %v", err)
	}
	if len(results) != 0 {
		t.Errorf("expected 0 results, got %d", len(results))
	}

	// Empty query
	results, err = idx.SearchEntries(ctx, "")
	if err != nil {
		t.Fatalf("SearchEntries empty: %v", err)
	}
	if len(results) != 0 {
		t.Errorf("expected 0 results, got %d", len(results))
	}
}

func TestEntryAnchors(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	if err := idx.UpsertEntry(ctx, dossiers.Entry{ID: "ent-1", Type: dossiers.EntryTypeInvariant, DossierScope: "core", Text: "first"}); err != nil {
		t.Fatalf("UpsertEntry: %v", err)
	}
	if err := idx.UpsertEntry(ctx, dossiers.Entry{ID: "ent-2", Type: dossiers.EntryTypeInvariant, DossierScope: "core", Text: "second"}); err != nil {
		t.Fatalf("UpsertEntry: %v", err)
	}

	if err := idx.UpsertEntryAnchors(ctx, "ent-1", []string{
		"internal/core/index/index.go",
		"internal/core/index/entries.go",
	}); err != nil {
		t.Fatalf("UpsertEntryAnchors ent-1: %v", err)
	}

	if err := idx.UpsertEntryAnchors(ctx, "ent-2", []string{
		"internal/core/ops/reader.go",
	}); err != nil {
		t.Fatalf("UpsertEntryAnchors ent-2: %v", err)
	}

	// Prefix search with LookupByAnchor
	ids, err := idx.LookupByAnchor(ctx, "internal/core/index")
	if err != nil {
		t.Fatalf("LookupByAnchor index: %v", err)
	}
	if len(ids) != 1 || ids[0] != "ent-1" {
		t.Errorf("expected ['ent-1'], got %v", ids)
	}

	ids, err = idx.LookupByAnchor(ctx, "internal/core")
	if err != nil {
		t.Fatalf("LookupByAnchor core: %v", err)
	}
	if len(ids) != 2 {
		t.Errorf("expected 2 results, got %v", ids)
	}

	// Exact match with LookupByAnchorExact
	ids, err = idx.LookupByAnchorExact(ctx, "internal/core/index/index.go")
	if err != nil {
		t.Fatalf("LookupByAnchorExact exact: %v", err)
	}
	if len(ids) != 1 || ids[0] != "ent-1" {
		t.Errorf("expected ['ent-1'], got %v", ids)
	}

	ids, err = idx.LookupByAnchorExact(ctx, "internal/core/index")
	if err != nil {
		t.Fatalf("LookupByAnchorExact partial: %v", err)
	}
	if len(ids) != 0 {
		t.Errorf("expected 0 results, got %v", ids)
	}
}

func TestErrorPatterns(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	if err := idx.UpsertEntry(ctx, dossiers.Entry{ID: "fail-timeout", Type: dossiers.EntryTypeFailureSignature, DossierScope: "core/test", Text: "Timeout error"}); err != nil {
		t.Fatalf("UpsertEntry: %v", err)
	}
	if err := idx.UpsertEntry(ctx, dossiers.Entry{ID: "fail-build", Type: dossiers.EntryTypeFailureSignature, DossierScope: "core/build", Text: "Build syntax error"}); err != nil {
		t.Fatalf("UpsertEntry: %v", err)
	}

	if err := idx.InsertErrorPattern(ctx, "fail-timeout", "go test", "test timed out", "core/test"); err != nil {
		t.Fatalf("InsertErrorPattern: %v", err)
	}
	if err := idx.InsertErrorPattern(ctx, "fail-build", "go build", "undefined symbol", "core/build"); err != nil {
		t.Fatalf("InsertErrorPattern: %v", err)
	}

	// Lookup by command prefix
	matches, err := idx.LookupErrorPatterns(ctx, "go test -v ./...")
	if err != nil {
		t.Fatalf("LookupErrorPatterns: %v", err)
	}
	if len(matches) != 1 {
		t.Fatalf("expected 1 match, got %d", len(matches))
	}
	if matches[0].EntryID != "fail-timeout" {
		t.Errorf("expected fail-timeout, got %s", matches[0].EntryID)
	}
	if matches[0].CommandPrefix != "go test" {
		t.Errorf("expected 'go test', got %s", matches[0].CommandPrefix)
	}
	if matches[0].Pattern != "test timed out" {
		t.Errorf("expected 'test timed out', got %s", matches[0].Pattern)
	}
	if matches[0].DossierScope != "core/test" {
		t.Errorf("expected 'core/test', got %s", matches[0].DossierScope)
	}

	matchesBuild, err := idx.LookupErrorPatterns(ctx, "go build")
	if err != nil {
		t.Fatalf("LookupErrorPatterns: %v", err)
	}
	if len(matchesBuild) != 1 || matchesBuild[0].EntryID != "fail-build" {
		t.Errorf("expected fail-build, got %v", matchesBuild)
	}
}

func TestAliases(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	// 1. Single alias
	if err := idx.UpsertAlias(ctx, "old/storage", "core/storage"); err != nil {
		t.Fatalf("UpsertAlias: %v", err)
	}
	resolved, err := idx.ResolveAlias(ctx, "old/storage")
	if err != nil {
		t.Fatalf("ResolveAlias: %v", err)
	}
	if resolved != "core/storage" {
		t.Errorf("expected core/storage, got %s", resolved)
	}

	// 2. Unaliased scope resolves to self
	resolvedSelf, err := idx.ResolveAlias(ctx, "core/storage")
	if err != nil {
		t.Fatalf("ResolveAlias self: %v", err)
	}
	if resolvedSelf != "core/storage" {
		t.Errorf("expected core/storage, got %s", resolvedSelf)
	}

	// 3. Alias chain: A -> B -> C
	if err := idx.UpsertAlias(ctx, "scope-a", "scope-b"); err != nil {
		t.Fatalf("UpsertAlias: %v", err)
	}
	if err := idx.UpsertAlias(ctx, "scope-b", "scope-c"); err != nil {
		t.Fatalf("UpsertAlias: %v", err)
	}
	resolvedChain, err := idx.ResolveAlias(ctx, "scope-a")
	if err != nil {
		t.Fatalf("ResolveAlias chain: %v", err)
	}
	if resolvedChain != "scope-c" {
		t.Errorf("expected scope-c, got %s", resolvedChain)
	}

	// 4. Cycle protection
	if err := idx.UpsertAlias(ctx, "cycle-1", "cycle-2"); err != nil {
		t.Fatalf("UpsertAlias: %v", err)
	}
	if err := idx.UpsertAlias(ctx, "cycle-2", "cycle-1"); err != nil {
		t.Fatalf("UpsertAlias: %v", err)
	}
	_, err = idx.ResolveAlias(ctx, "cycle-1")
	if err != nil {
		t.Errorf("cycle resolution should not fail with error: %v", err)
	}
}

func TestHistory(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	now := time.Now().UTC().Truncate(time.Second)
	histEntry := dossiers.Entry{
		ID:           "inv-legacy-1",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/legacy",
		Text:         "Legacy file format must be maintained",
		SupersededBy: "inv-v2-1",
		UpdatedAt:    now,
	}

	if err := idx.InsertHistory(ctx, histEntry, "superseded by v2 format"); err != nil {
		t.Fatalf("InsertHistory: %v", err)
	}

	history, err := idx.GetHistory(ctx, "inv-legacy-1")
	if err != nil {
		t.Fatalf("GetHistory: %v", err)
	}
	if len(history) != 1 {
		t.Fatalf("expected 1 history record, got %d", len(history))
	}

	h := history[0]
	if h.ID != "inv-legacy-1" {
