func TestRebuildFromOpLogEndToEnd(t *testing.T) {
	ctx := context.Background()
	opsDir := filepath.Join(t.TempDir(), "ops")
	writer := ops.NewWriter(opsDir)

	now := time.Now().UTC()
	// Write batch 1: add invariant, failure-signature, and an entry to retire
	batch1 := ops.NewBatch([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-rebuild-1",
			DossierScope: "core/storage",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"entry_type": "invariant",
				"text":       "Rebuild invariant text",
				"anchors":    []string{"internal/core/storage/file.go"},
			},
		},
		{
			Type:         ops.OpAdd,
			EntryID:      "fail-rebuild-1",
			DossierScope: "core/build",
			Timestamp:    now,
			Source:       ops.SourceSidecar,
			Fields: map[string]any{
				"entry_type":     "failure-signature",
				"text":           "Build failure on macos",
				"command_prefix": "go build",
				"pattern":        "cgo: C compiler not found",
				"anchors":        []string{"cmd:go build"},
			},
		},
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-to-retire",
			DossierScope: "core/legacy",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"entry_type": "invariant",
				"text":       "Will be retired soon",
			},
		},
		{
			Type:         ops.OpSplit,
			DossierScope: "legacy/combined",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"new_dossiers": []string{"legacy/split1", "legacy/split2"},
				"entry_moves":  map[string]string{},
			},
		},
	})
	if err := writer.Write(batch1); err != nil {
		t.Fatalf("Write batch1: %v", err)
	}

	// Write batch 2: retire inv-to-retire
	batch2 := ops.NewBatch([]ops.Op{
		{
			Type:         ops.OpRetire,
			EntryID:      "inv-to-retire",
			DossierScope: "core/legacy",
			Timestamp:    now.Add(time.Minute),
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"reason": "deprecated in v2",
			},
		},
	})
	if err := writer.Write(batch2); err != nil {
		t.Fatalf("Write batch2: %v", err)
	}

	// Create new index and rebuild from op log
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	opsReader := ops.NewReader(opsDir)
	if err := idx.RebuildFromOpLog(ctx, opsReader); err != nil {
		t.Fatalf("RebuildFromOpLog: %v", err)
	}

	// 1. Verify invariant entry
	entry, err := idx.GetEntry(ctx, "inv-rebuild-1")
	if err != nil {
		t.Fatalf("GetEntry inv-rebuild-1: %v", err)
	}
	if entry.Text != "Rebuild invariant text" {
		t.Errorf("expected text 'Rebuild invariant text', got %s", entry.Text)
	}
	if len(entry.Anchors) != 1 || entry.Anchors[0] != "internal/core/storage/file.go" {
		t.Errorf("anchors mismatch: %v", entry.Anchors)
	}

	// 2. Verify anchor lookup
	anchorIDs, err := idx.LookupByAnchor(ctx, "internal/core/storage")
	if err != nil {
		t.Fatalf("LookupByAnchor: %v", err)
	}
	if len(anchorIDs) != 1 || anchorIDs[0] != "inv-rebuild-1" {
		t.Errorf("expected ['inv-rebuild-1'], got %v", anchorIDs)
	}

	// 3. Verify error pattern
	errPats, err := idx.LookupErrorPatterns(ctx, "go build ./...")
	if err != nil {
		t.Fatalf("LookupErrorPatterns: %v", err)
	}
	if len(errPats) != 1 || errPats[0].EntryID != "fail-rebuild-1" {
		t.Errorf("expected fail-rebuild-1, got %v", errPats)
	}
	if errPats[0].Pattern != "cgo: C compiler not found" {
		t.Errorf("pattern mismatch: %s", errPats[0].Pattern)
	}

	// 4. Verify alias from split op
	resolvedScope, err := idx.ResolveAlias(ctx, "legacy/combined")
	if err != nil {
		t.Fatalf("ResolveAlias: %v", err)
	}
	if resolvedScope != "legacy/split1" {
		t.Errorf("expected legacy/split1, got %s", resolvedScope)
	}

	// 5. Verify retired entry in history
	_, err = idx.GetEntry(ctx, "inv-to-retire")
	if err == nil {
		t.Errorf("retired entry should not be in active entries table")
	}
	history, err := idx.GetHistory(ctx, "inv-to-retire")
	if err != nil {
		t.Fatalf("GetHistory inv-to-retire: %v", err)
	}
	if len(history) != 1 {
		t.Fatalf("expected 1 history record, got %d", len(history))
	}
	if history[0].RetiredReason != "deprecated in v2" {
		t.Errorf("expected reason 'deprecated in v2', got %s", history[0].RetiredReason)
	}

	// 6. Verify FTS search
	searchResults, err := idx.SearchEntries(ctx, "rebuild")
	if err != nil {
		t.Fatalf("SearchEntries: %v", err)
	}
	if len(searchResults) < 1 {
		t.Errorf("expected at least 1 search result, got %d", len(searchResults))
	}
}

